import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
/** Verifies original authoring glue against installed native APIs without starting the game. */
public final class GameplayGameProbe {
 public static void main(String[] args)throws Exception{
  Class<?> random=c("zombie.core.random.RandStandard");random.getMethod("init").invoke(random.getField("INSTANCE").get(null));Class<?> cell=c("zombie.iso.IsoCell"),square=c("zombie.iso.IsoGridSquare"),thump=c("zombie.iso.objects.IsoThumpable"),sprite=c("zombie.iso.sprite.IsoSprite"),table=c("se.krka.kahlua.vm.KahluaTable"),light=c("zombie.iso.IsoLightSource");
  thump.getConstructor(cell,square,String.class,String.class,boolean.class,table);thump.getMethod("setIsDoor",boolean.class);thump.getMethod("setLockedByKey",boolean.class);thump.getMethod("setKeyId",int.class);thump.getMethod("IsOpen");thump.getMethod("ToggleDoorSilent");thump.getMethod("setLightSource",light);thump.getMethod("setLightSourceOn",boolean.class);thump.getMethod("setLightSourceRadius",int.class);cell.getMethod("addLamppost",light);cell.getMethod("removeLamppost",light);square.getMethod("transmitRemoveItemFromSquare",c("zombie.iso.IsoObject"));c("zombie.world.moddata.ModData").getMethod("getOrCreate",String.class);
  c("zombie.inventory.ItemPickerJava").getMethod("getItemContainer",String.class,String.class,String.class,boolean.class);c("zombie.inventory.ItemPickerJava").getMethod("doRollItem",c("zombie.inventory.ItemPickerJava$ItemPickerContainer"),c("zombie.inventory.ItemContainer"),float.class,c("zombie.characters.IsoGameCharacter"),boolean.class,c("zombie.inventory.ItemPickerJava$ItemPickerRoom"));
  Constructor<?> sq=square.getConstructor(cell,c("zombie.iso.SliceY"),int.class,int.class,int.class);Object target=sq.newInstance(null,null,100,100,0);Method collide=thump.getMethod("TestCollide",c("zombie.iso.IsoMovingObject"),square,square);
  for(boolean north:new boolean[]{true,false}){Object door=thump.getConstructor(cell).newInstance(new Object[]{null});thump.getMethod("setSquare",square).invoke(door,target);thump.getMethod("setSprite",sprite).invoke(door,sprite.getConstructor().newInstance());thump.getField("north").setBoolean(door,north);thump.getMethod("setIsDoor",boolean.class).invoke(door,true);thump.getMethod("setCanPassThrough",boolean.class).invoke(door,false);thump.getMethod("setBlockAllTheSquare",boolean.class).invoke(door,false);Object objects=square.getMethod("getSpecialObjects").invoke(target);objects.getClass().getMethod("add",Object.class).invoke(objects,door);Object normal=square.getMethod("getObjects").invoke(target);normal.getClass().getMethod("add",Object.class).invoke(normal,door);thump.getMethod("setKeyId",int.class).invoke(door,55);if((int)thump.getMethod("getKeyId").invoke(door)!=55)throw new AssertionError("Native key ID absent");thump.getMethod("setLockedByKey",boolean.class).invoke(door,true);if(!(boolean)thump.getMethod("isLockedByKey").invoke(door))throw new AssertionError("Native key lock absent");
   Object edge=sq.newInstance(null,null,north?100:99,north?99:100,0);Object other=sq.newInstance(null,null,north?99:100,north?100:99,0);if(!(boolean)collide.invoke(door,null,edge,target)||(boolean)collide.invoke(door,null,other,target))throw new AssertionError("Native closed door edge topology differs");// ToggleDoorSilent needs a populated world cell; inspect native collision for an authored open state without starting a session.
thump.getField("open").setBoolean(door,true);if(!(boolean)thump.getMethod("IsOpen").invoke(door)||(int)thump.getMethod("getKeyId").invoke(door)!=55||!(boolean)thump.getMethod("isLockedByKey").invoke(door))throw new AssertionError("Native opening lost authored key state");if((boolean)collide.invoke(door,null,edge,target)||(boolean)collide.invoke(door,null,other,target))throw new AssertionError("Native open door must allow both edges");System.out.println("Native "+(north?"north":"west")+" door blocks its closed edge, allows both edges when open, and preserves key lock.");
  }
  Object source=light.getConstructor(int.class,int.class,int.class,float.class,float.class,float.class,int.class).newInstance(100,100,-1,1f,.2f,.1f,9);light.getMethod("setActive",boolean.class).invoke(source,true);if(Math.abs(light.getField("g").getFloat(source)-.2f)>.001||light.getField("radius").getInt(source)!=9||light.getField("z").getInt(source)!=-1)throw new AssertionError("Native source RGB/radius/floor changed");System.out.println("Installed IsoLightSource preserves authored RGB, radius and basement level.");
  Object props=c("se.krka.kahlua.j2se.KahluaTableImpl").getConstructor(Map.class).newInstance(new HashMap<>());table.getMethod("rawset",Object.class,Object.class).invoke(props,"Direction","E");table.getMethod("rawset",Object.class,Object.class).invoke(props,"FaceDirection",true);Class<?> vehicle=c("zombie.iso.zones.VehicleZone");Object zone=vehicle.getConstructor(String.class,String.class,int.class,int.class,int.class,int.class,int.class,table).newInstance("parkingstall","ParkingStall",100,100,0,3,5,props);if(!vehicle.getField("dir").get(zone).toString().equals("E")||vehicle.getField("flags").getInt(zone)==0)throw new AssertionError("Native vehicle direction properties lost");System.out.println("Installed VehicleZone reads Direction E and FaceDirection true.");
  int compiled=0,parsed=0;for(String arg:args){String value=Files.readString(Path.of(arg));if(arg.endsWith(".lua")){Object closure=c("se.krka.kahlua.luaj.compiler.LuaCompiler").getMethod("loadstring",String.class,String.class,table).invoke(null,value,"Original authoring glue",null);if(closure==null)throw new AssertionError("Missing Lua closure");compiled++;}else if(arg.endsWith(".txt")){c("zombie.scripting.ScriptParser").getMethod("parse",String.class).invoke(null,value);parsed++;}}
  if(compiled<3||parsed<1)throw new AssertionError("Generate interactive fixture with Core tests before running this probe.");System.out.println("PASS installed native gameplay APIs and "+compiled+" original Lua files compiled, "+parsed+" original script declarations parsed; no game client or external mod Lua executed.");
 }
 private static Class<?> c(String name)throws Exception{return Class.forName(name,false,GameplayGameProbe.class.getClassLoader());}
}
